请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-005

=== 用户原始指令 (query.txt) ===
整个快递卡，列一串我的包裹，写一句还有几个待取，点一下能跳到快递app里

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个快递卡，列一串我的包裹，写一句还有几个待取，点一下能跳到快递app里",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hiexpress://packages"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "express": {
        "title": {
          "type": "string",
          "description": "快递物流卡片标题",
          "sampleValue": "我的包裹"
        },
        "summaryText": {
          "type": "string",
          "description": "包裹列表的简短汇总",
          "sampleValue": "3个包裹更新中"
        },
        "pendingPickupText": {
          "type": "string",
          "description": "当前仍待取的包裹数量提示",
          "sampleValue": "还有2件待取"
        },
        "packages": {
          "type": "array",
          "description": "需要在卡片上展示的包裹列表",
          "sampleValue": [
            {
              "name": "耳机配件",
              "statusText": "丰巢待取"
            },
            {
              "name": "纸巾补给",
              "statusText": "派送中"
            },
            {
              "name": "文件袋",
              "statusText": "已揽收"
            }
          ],
          "items": {
            "type": "object",
            "description": "单个包裹的展示信息",
            "sampleValue": {
              "name": "耳机配件",
              "statusText": "丰巢待取"
            },
            "properties": {
              "name": {
                "type": "string",
                "description": "包裹名称或脱敏后的物品简称",
                "sampleValue": "耳机配件"
              },
              "statusText": {
                "type": "string",
                "description": "包裹当前物流状态的短文本",
                "sampleValue": "丰巢待取"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱图标，适合用于物流信息、包裹列表和取件提醒的视觉识别。"
    }
  ]
}

